import json, io, os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
NB = os.path.join(HERE, "main.ipynb")
nb = json.load(io.open(NB, encoding="utf-8"))

def lines(s):
    parts = s.split("\n")
    return [p + "\n" for p in parts[:-1]] + ([parts[-1]] if parts[-1] != "" else [])

CELL_ADHOC = 'elements = [Spacer(1, 2)]\n\nassessmentId = 48334  # ← change this for the entry you want\n\nrow  = readDf(engine, INDIVIDUAL_ENTRY_SQL, {"assessmentId": assessmentId}).iloc[0]\nmcDf = readDf(engine, INDIVIDUAL_MC_SQL,    {"assessmentId": assessmentId})\nitemDescMap = getItemCodeDescriptionMap(engine, row["cohort"])\n\ndoc = SimpleDocTemplate("BOH3_DDS4/Student_Detailed_Entry_Test.pdf",\n    pagesize=pageSize, rightMargin=rightMargin, leftMargin=leftMargin,\n    topMargin=topMargin, bottomMargin=bottomMargin)\n\nbuildIndividualEntryPage(elements, row, mcDf, itemDescMap=itemDescMap)\n\n# CAF navy/white header + footer (course · date · ID  /  student | assessor | clinic)\npage_state = cafHeaderFooterFields(row)\ndecorator  = getCafPageDecorator(page_state)\ndoc.build(elements, onFirstPage=decorator, onLaterPages=decorator)'
CELL_STUDENT = 'from reportlab.platypus import Table, TableStyle\nfrom reportlab.lib import colors\nfrom reportlab.lib.styles import ParagraphStyle\nfrom boh3_dds4_utils import _BookmarkAnchor, CafHeaderMarker\n\nstudentNumber = 1082018\n\nentryDf = readDf(engine, STUDENT_ENTRIES_SQL, {"studentNumber": studentNumber})\nallMcDf = readDf(engine, STUDENT_MC_SQL,      {"studentNumber": studentNumber})\nprint(f"Length of entryDf: {len(entryDf)}, Length of allMcDf: {len(allMcDf)}")\nstudentName    = entryDf.iloc[0]["student_name"]\nstudentNumber_ = entryDf.iloc[0]["student_number"]\nitemDescMap    = getItemCodeDescriptionMap(engine, entryDf.iloc[0]["cohort"])\n\n# ── TOC ─────────────────────────────────────────────\nlinkStyle = ParagraphStyle("link", parent=tableTextStyleSmall,\n                           textColor=colors.HexColor("#1155CC"))\navailWidth = pageSize[0] - leftMargin - rightMargin\ncolWidths  = [availWidth * r for r in [0.1, 0.2, 0.3, 0.3, 0.1]]\ntocRows = [[Paragraph("<b>Form</b>",              tableTextStyleWhite),\n            Paragraph("<b>Date</b>",              tableTextStyleWhite),\n            Paragraph("<b>Clinic</b>",            tableTextStyleWhite),\n            Paragraph("<b>Rotation</b>",          tableTextStyleWhite),\n            Paragraph("<b>Assessor Submitted</b>", tableTextStyleWhite)]]\nfor i, (_, row) in enumerate(entryDf.iterrows()):\n    date_str = f"{row[\'created_date\'].day} {row[\'created_date\'].strftime(\'%B %Y\')}"\n    anchor   = f"form_{i}"\n    tocRows.append([\n        Paragraph(f\'<link href="#{anchor}"><u>Form {i + 1}</u></link>\', linkStyle),\n        Paragraph(date_str,                      tableTextStyleSmall),\n        Paragraph(row["clinic"]   or "—",   tableTextStyleSmall),\n        Paragraph(row["rotation"] or "—",   tableTextStyleSmall),\n        Paragraph("Yes" if row["submitted_by_assessor"] else "No", tableTextStyleSmall),\n    ])\ntocTable = Table(tocRows, colWidths=colWidths, repeatRows=1)\ntocTable.setStyle(TableStyle([\n    ("BACKGROUND",    (0, 0), (-1, 0),  uniColor),\n    ("TEXTCOLOR",     (0, 0), (-1, 0),  colors.white),\n    ("FONTNAME",      (0, 0), (-1, 0),  "Helvetica-Bold"),\n    ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F3F4F6")]),\n    ("GRID",          (0, 0), (-1, -1), 0.5, colors.HexColor("#CCCCCC")),\n    ("TOPPADDING",    (0, 0), (-1, -1), 5),\n    ("BOTTOMPADDING", (0, 0), (-1, -1), 5),\n    ("LEFTPADDING",   (0, 0), (-1, -1), 6),\n]))\n\n# ── CAF page header/footer, refreshed per form via page_state ─────────────\npage_state = dict(cafHeaderFooterFields(entryDf.iloc[0]))\ndecorator  = getCafPageDecorator(page_state)\n\ndoc = SimpleDocTemplate(\n    f"BOH3_DDS4/Student_Report_{studentNumber_}.pdf",\n    pagesize=pageSize, rightMargin=rightMargin, leftMargin=leftMargin,\n    topMargin=topMargin, bottomMargin=bottomMargin,\n)\n\nelements = [Spacer(1, 2), Paragraph("Assessment Index", subheadingStyle),\n            Spacer(1, 8), tocTable]\n\nfor i, (_, row) in enumerate(entryDf.iterrows()):\n    anchor = f"form_{i}"\n    elements.append(CafHeaderMarker(cafHeaderFooterFields(row), page_state))  # before PageBreak → state ready for onLaterPages\n    elements.append(PageBreak())\n    elements.append(_BookmarkAnchor(anchor))              # after PageBreak → bookmark on correct page\n    elements.append(Spacer(1, 2))\n    mcDf = allMcDf[allMcDf["assessmentid"] == row["assessmentid"]].reset_index(drop=True)\n    buildIndividualEntryPage(elements, row, mcDf, itemDescMap=itemDescMap)\n\ndoc.build(elements, onFirstPage=decorator, onLaterPages=decorator)'
targets = {"2c70afb1": CELL_ADHOC, "ff349421": CELL_STUDENT}
done = []
for cell in nb["cells"]:
    if cell.get("id") in targets:
        cell["source"] = lines(targets[cell["id"]])
        cell["outputs"] = []
        cell["execution_count"] = None
        done.append(cell["id"])
if sorted(done) != sorted(targets):
    print("ERROR missing cells:", set(targets)-set(done)); sys.exit(1)
json.dump(nb, io.open(NB, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print("patched cells:", sorted(done))
